THOUGHT: Based on my analysis, I believe I've identified the issue in the `findNode` function in vim.go. When navigating to a specific line number, if that line is within collapsed content, the current implementation skips over the entire collapsed section without checking if the target line is inside it.

The fix should modify the `findNode` function to properly handle collapsed nodes by checking if the target line number falls within the range of the collapsed content before skipping it.

Here's my proposed fix:

```bash
cat <<'EOF' > vim.go.fixed
package main

import (
	"strconv"

	tea "github.com/charmbracelet/bubbletea"

	. "github.com/antonmedv/fx/internal/jsonx"
)

func (m *model) runCommand(s string) (tea.Model, tea.Cmd) {
	num, err := strconv.Atoi(s)
	if err == nil {
		gotoLine(m, num)
		return m, nil
	} else if s == "q" {
		return m, tea.Quit
	}
	return m, nil
}

func gotoLine(m *model, num int) {
	m.selectNode(findNode(m, num))

	m.commandInput.SetValue("")
	m.recordHistory()
}

func findNode(m *model, line int) *Node {
	if line >= m.totalLines {
		return m.top.Bottom()
	}

	if line <= 1 {
		return m.top
	}

	node := m.top

	for {
		// Check if target line is within this collapsed node's range
		if node.IsCollapsed() && node.Collapsed != nil && node.End != nil {
			// Check if the target line falls within the collapsed content
			if line >= node.Collapsed.LineNumber && line <= node.End.LineNumber {
				// Expand the node to allow searching within its content
				node.Expand()
				// Continue with normal iteration
				if node.ChunkEnd != nil {
					node = node.ChunkEnd.Next
				} else {
					node = node.Next
				}
			} else {
				// Target line is not in collapsed content, skip it
				node = node.End.Next
			}
		} else if node.ChunkEnd != nil {
			node = node.ChunkEnd.Next
		} else {
			node = node.Next
		}

		if node == nil {
			return nil
		}

		if node.LineNumber == line {
			return node
		}
	}
}
EOF
```

